            List<Map<String,Object>> rows = jdbc.queryForList("SELECT c.*,d.title FROM native_rag_chunk c JOIN native_rag_document d ON c.document_id=d.id WHERE c.kb_id IN (" + placeholders + ") ORDER BY c.id LIMIT " + (MAX_SEARCH_CHUNKS + 1), ids.toArray());
